#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
long long rob(vector<long long>&v){long long p2=0,p1=0;
for(long long x:v){long long c=max(p1,p2+x);p2=p1;p1=c;}return p1;}
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
if(n==1){printf("%lld\n",a[0]);return 0;}
vector<long long>x(a.begin(),a.end()-1),y(a.begin()+1,a.end());
printf("%lld\n",max(rob(x),rob(y)));return 0;}

